{"contents":"	"contributes": {
		"configuration": {
			"title": "SpecStory",
			"properties": {
				"specstory.cloudSync.enabled": {
					"order": 1,
					"scope": "window",
					"type": "string",
					"enum": [
						"always",
						"ask",
						"never"
					],
					"enumDescriptions": [
						"Enable Cloud Sync for all projects by default",
						"Ask for each new project (default)",
						"Disable Cloud Sync for all projects by default"
					],
					"default": "ask",
					"description": "Cloud sync behavior. Can be overridden at workspace level. 'always' enables sync, 'ask' prompts per new project, 'never' disables sync.\n\nNOTE: Requires login to SpecStory.",
					"markdownDescription": "Cloud sync behavior. Can be overridden at workspace level. `always` enables sync, `ask` prompts per new project, `never` disables sync.\n\nNOTE: Requires login to SpecStory."
				},
				"specstory.autoSave.enabled": {
					"order": 2,
					"type": "boolean",
					"default": true,
					"description": "Automatically save AI chat history into the ./.specstory directory"
				},
				"specstory.outputPath": {
					"order": 2.5,
					"type": "string",
					"default": "",
					"scope": "resource",
					"description": "Directory path for storing SpecStory files, relative to the workspace root. If provided, the path must be within the workspace and all exported markdown files, .project.json, and statistics.json will be saved there. Default: .specstory",
					"markdownDescription": "Directory path for storing SpecStory files, relative to the workspace root.\n\nIf provided, the path must be within the workspace. All exported markdown files, `.project.json`, and `statistics.json` will be saved to this directory.\n\n**Default:** `.specstory`\n\n**Examples:**\n- `.specstory` (default)\n- `.ai-chats`\n- `docs/ai-sessions`"
				},
				"specstory.providers.enabled": {
					"order": 3,
					"type": "object",
					"properties": {
						"Cursor IDE": {
							"type": "boolean",
							"default": true
						},
						"Copilot IDE": {
							"type": "boolean",
							"default": true
						},
						"Claude Code": {
							"type": "boolean",
							"default": true
						},
						"Factory Droid CLI": {
							"type": "boolean",
							"default": true
						},
						"Cursor CLI": {
							"type": "boolean",
							"default": true
						},
						"Gemini CLI": {
							"type": "boolean",
							"default": true
						},
						"Codex CLI": {
							"type": "boolean",
							"default": true
						}
					},
					"default": {
						"Cursor IDE": true,
						"Copilot IDE": true,
						"Claude Code": true,
						"Factory Droid CLI": true,
						"Cursor CLI": true,
						"Gemini CLI": true,
						"Codex CLI": true
					},
					"description": "Providers to include in SpecStory. All providers are enabled by default.",
					"additionalProperties": false
				},
				"specstory.coordinatedUniversalTimezone": {
					"order": 5,
					"type": "boolean",
					"default": true,
					"description": "Use Coordinated Universal Time (UTC) timezone. If unchecked, the local timezone will be used instead.",
					"markdownDescription": "Use Coordinated Universal Time (UTC) timezone. If unchecked, the local timezone will be used instead."
				},
				"specstory.helpUsImprove": {
					"order": 6,
					"type": "boolean",
					"default": true,
					"description": "To make SpecStory better this option lets us collect usage data from the extension. This includes questions in chat, code snippets, edits, and editor actions. This setting does not affect web analytics. See our [privacy policy](https://specstory.com/privacy) for details.",
					"markdownDescription": "To make SpecStory better this option lets us collect usage data from the extension. This includes questions in chat, code snippets, edits, and editor actions. This setting does not affect web analytics. See our [privacy policy](https://specstory.com/privacy) for details."
				},
				"specstory.showDeveloperTools": {
					"order": 7,
					"type": "boolean",
					"default": false,
					"description": "Show developer logging and developer tools"
				}
			}
		},
		"views": {
			"specstory": [
				{
					"id": "specstory.controlPanel",
					"name": "SpecStory",
					"type": "webview"
				}
			]
		},
		"viewsContainers": {
			"activitybar": [
				{
					"id": "specstory",
					"title": "SpecStory",
					"icon": "resources/specstory.svg"
				}
			]","totalLinesInFile":272}
